#include "PluginEditor.h"
#include <limits>
#include "Seer12UI.h"   // generated by juce_add_binary_data(Seer12UI ...) from Source12/ui/*

namespace
{
juce::String mimeFor(const juce::String& path)
{
    const auto ext = path.fromLastOccurrenceOf(".", false, false).toLowerCase();
    if (ext == "html") return "text/html";
    if (ext == "css")  return "text/css";
    if (ext == "js")   return "text/javascript";
    if (ext == "svg")  return "image/svg+xml";
    if (ext == "png")  return "image/png";
    if (ext == "woff2") return "font/woff2";
    if (ext == "json") return "application/json";
    return "application/octet-stream";
}

std::vector<std::byte> toBytes(const void* data, size_t size)
{
    const auto* p = static_cast<const std::byte*>(data);
    return { p, p + size };
}
}  // namespace

//==============================================================================
Seer12Editor::Seer12Editor(Seer12Processor& p)
    : AudioProcessorEditor(&p),
      processor(p),
      settingsPanel(p),
      webView(makeBrowserOptions())
{
    settingsPanel.setLookAndFeel(&lookAndFeel);
    addChildComponent(settingsPanel);  // hidden until the gear is clicked

    for (int i = 0; i < p12::kNumParams; ++i)
    {
        params[(size_t) i] = processor.apvts.getParameter(p12::kParams[i].id);
        lastSent[(size_t) i] = std::numeric_limits<int>::min();
        indexById[p12::kParams[i].id] = i;
    }

    addAndMakeVisible(webView);
    webView.goToURL(juce::WebBrowserComponent::getResourceProviderRoot());

    // The page is designed at 1440x880 and scales itself to fit, so keep the
    // window at that aspect ratio.
    setResizable(true, true);
    setResizeLimits(kDesignWidth / 2, kDesignHeight / 2, kDesignWidth * 2, kDesignHeight * 2);
    if (auto* c = getConstrainer())
        c->setFixedAspectRatio((double) kDesignWidth / (double) kDesignHeight);
    setSize(1200, (int) std::round(1200.0 * kDesignHeight / kDesignWidth));

    startTimerHz(30);
}

Seer12Editor::~Seer12Editor()
{
    stopTimer();
    settingsPanel.setLookAndFeel(nullptr);
}

juce::WebBrowserComponent::Options Seer12Editor::makeBrowserOptions()
{
    using Options = juce::WebBrowserComponent::Options;

    // WebView2 needs a writable user-data folder; a host's install folder
    // usually isn't, so point it at the temp directory.
    const auto userData = juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("Seer12WebView2");

    return Options {}
        .withBackend(Options::Backend::webview2)
        .withWinWebView2Options(Options::WinWebView2 {}
                                    .withUserDataFolder(userData)
                                    .withStatusBarDisabled()
                                    .withBackgroundColour(juce::Colour(0xff121318)))
        .withNativeIntegrationEnabled()
        .withKeepPageLoadedWhenBrowserIsHidden()
        .withResourceProvider([this](const juce::String& url) { return getResource(url); })
        .withEventListener("seer:ready", [this](const juce::var&)
        {
            uiReady = true;
            pushValues(true);
            pushStatus(true);
            pushPresetList();
        })
        .withEventListener("seer:program", [this](const juce::var& v)
        {
            const int delta = (int) v.getProperty("delta", 0);
            if (delta != 0)
                processor.changeProgram(delta > 0 ? 1 : -1);
        })
        .withEventListener("seer:sync", [this](const juce::var&) { processor.requestEditBufferDump(); })
        .withEventListener("seer:settings", [this](const juce::var&)
        {
            settingsOpen = ! settingsOpen;
            settingsPanel.setVisible(settingsOpen);
            resized();
        })
        .withEventListener("seer:presetList", [this](const juce::var&) { pushPresetList(); })
        .withEventListener("seer:presetLoad", [this](const juce::var& v)
        {
            if (processor.loadPreset(v.getProperty("name", "").toString()))
            {
                pushValues(true);
                pushPresetList();
            }
        })
        .withEventListener("seer:presetStep", [this](const juce::var& v)
        {
            const int delta = (int) v.getProperty("delta", 1);
            if (processor.stepPreset(delta).isNotEmpty())
            {
                pushValues(true);
                pushPresetList();
            }
        })
        .withEventListener("seer:presetSave", [this](const juce::var& v)
        {
            processor.savePresetAs(v.getProperty("name", "").toString());
            pushPresetList();
        })
        .withEventListener("seer:presetDelete", [this](const juce::var& v)
        {
            processor.deletePreset(v.getProperty("name", "").toString());
            pushPresetList();
        })
        .withEventListener("seer:set", [this](const juce::var& v) { handleSet(v); })
        .withEventListener("seer:gesture", [this](const juce::var& v) { handleGesture(v); });
}

//==============================================================================
std::optional<juce::WebBrowserComponent::Resource> Seer12Editor::getResource(const juce::String& url)
{
    auto path = url.upToFirstOccurrenceOf("?", false, false).fromFirstOccurrenceOf("/", false, false);
    if (path.isEmpty())
        path = "index.html";
    const auto fileName = path.fromLastOccurrenceOf("/", false, false);

    // Dev mode: serve straight from disk if SEER12_UI_DIR is set.
    const auto devDir = juce::SystemStats::getEnvironmentVariable("SEER12_UI_DIR", {});
    if (devDir.isNotEmpty())
    {
        const auto f = juce::File(devDir).getChildFile(fileName);
        juce::MemoryBlock mb;
        if (f.existsAsFile() && f.loadFileAsData(mb))
            return juce::WebBrowserComponent::Resource { toBytes(mb.getData(), mb.getSize()), mimeFor(fileName) };
    }

    // Normal mode: compiled-in binary data. The ui/ folder is flat, so match
    // on the original file name.
    for (int i = 0; i < Seer12UI::namedResourceListSize; ++i)
    {
        if (fileName == Seer12UI::originalFilenames[i])
        {
            int size = 0;
            if (const auto* data = Seer12UI::getNamedResource(Seer12UI::namedResourceList[i], size))
                return juce::WebBrowserComponent::Resource { toBytes(data, (size_t) size), mimeFor(fileName) };
        }
    }

    return std::nullopt;
}

//==============================================================================
juce::RangedAudioParameter* Seer12Editor::paramFor(const juce::var& idVar) const
{
    const auto it = indexById.find(idVar.toString());
    return it == indexById.end() ? nullptr : params[(size_t) it->second];
}

void Seer12Editor::handleSet(const juce::var& payload)
{
    auto* param = paramFor(payload.getProperty("id", {}));
    if (param == nullptr)
        return;

    // The UI sends the real value (an integer index / step); convert to 0..1.
    const auto real = (float) (double) payload.getProperty("value", 0);
    param->setValueNotifyingHost(param->convertTo0to1(real));

    // Remember what the UI already shows so the poll doesn't echo it back.
    const auto idx = indexById.at(payload.getProperty("id", {}).toString());
    lastSent[(size_t) idx] = juce::roundToInt(param->convertFrom0to1(param->getValue()));
}

void Seer12Editor::handleGesture(const juce::var& payload)
{
    if (auto* param = paramFor(payload.getProperty("id", {})))
    {
        if ((bool) payload.getProperty("begin", false))
            param->beginChangeGesture();
        else
            param->endChangeGesture();
    }
}

void Seer12Editor::pushValues(bool fullSnapshot)
{
    if (! uiReady)
        return;

    juce::DynamicObject::Ptr obj = new juce::DynamicObject();
    bool any = false;

    for (int i = 0; i < p12::kNumParams; ++i)
    {
        auto* param = params[(size_t) i];
        if (param == nullptr)
            continue;
        const int value = juce::roundToInt(param->convertFrom0to1(param->getValue()));
        if (fullSnapshot || value != lastSent[(size_t) i])
        {
            obj->setProperty(p12::kParams[i].id, value);
            lastSent[(size_t) i] = value;
            any = true;
        }
    }

    if (any)
        webView.emitEventIfBrowserIsVisible("seer:params", juce::var(obj.get()));
}

void Seer12Editor::pushStatus(bool force)
{
    if (! uiReady)
        return;

    const int seq = processor.fullSyncSequence.load();
    const auto link = processor.directLink.statusText();
    if (! force && seq == lastStatusSeq && link == lastLinkText)
        return;
    lastStatusSeq = seq;
    lastLinkText = link;

    juce::DynamicObject::Ptr obj = new juce::DynamicObject();
    obj->setProperty("patch", processor.getLastSyncedPatchName());
    obj->setProperty("link", link);
    obj->setProperty("synced", processor.fullSyncAppliedCount.load());
    obj->setProperty("seq", seq);
    webView.emitEventIfBrowserIsVisible("seer:status", juce::var(obj.get()));
}

void Seer12Editor::pushPresetList()
{
    if (! uiReady)
        return;

    juce::Array<juce::var> names;
    for (const auto& n : processor.getPresetNames())
        names.add(n);

    juce::DynamicObject::Ptr obj = new juce::DynamicObject();
    obj->setProperty("names", names);
    obj->setProperty("current", processor.getCurrentPresetName());
    webView.emitEventIfBrowserIsVisible("seer:presetList", juce::var(obj.get()));
}

void Seer12Editor::timerCallback()
{
    // Picks up host automation, hardware knob moves (decoded from MIDI by the
    // processor) and full-dump syncs, and forwards only what changed.
    pushValues(false);
    pushStatus(false);
}

//==============================================================================
void Seer12Editor::paint(juce::Graphics& g)
{
    g.fillAll(juce::Colour(0xff121318));
}

void Seer12Editor::resized()
{
    auto b = getLocalBounds();
    if (settingsOpen)
        settingsPanel.setBounds(b.removeFromBottom(SettingsPanel::kPreferredHeight));
    webView.setBounds(b);
}
